#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_remove_digits_non_null_multi_node_positive_N(void) {
    // Setup: create a big_int list with at least 2 nodes
    // Path conditions: digit != NULL, digit->next_digit != NULL, N > 0
    char values[] = {5, 3, 7};
    big_int *list = helper_create_big_int(values, 3);
    TEST_ASSERT_NOT_NULL(list);
    TEST_ASSERT_NOT_NULL(list->next_digit); // Ensure condition digit->next_digit != NULL

    int N = 2; // N > 0 to trigger the recursive call with N-1

    // Test: call remove_digits with N > 0
    // According to the path, this should recursively call remove_digits(digit->next_digit, N-1)
    // The function always returns 0
    char result = remove_digits(list, N);
    TEST_ASSERT_EQUAL_CHAR(0, result);

    // The function frees nodes from position N onward, but we cannot directly assert
    // that memory is freed. However, we can verify that the list is still accessible
    // for the first N nodes (though the function may have freed some nodes).
    // Since the function frees from N onward, the first N nodes should remain.
    // For safety, we only assert the return value.

    // Cleanup: free any remaining nodes using helper_free_big_int
    // Note: remove_digits may have freed some nodes, but helper_free_big_int
    // should handle partial freeing (or we can call remove_digits with N <= 0 to free all).
    // Use helper_free_big_int which calls remove_digits internally.
    helper_free_big_int(list);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_remove_digits_non_null_multi_node_positive_N);
    return UNITY_END();
}

